<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, shallowRef } from 'vue'
import type * as Monaco from 'monaco-editor/esm/vs/editor/editor.api'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Close, Folder, MoreFilled, Plus, Search } from '@element-plus/icons-vue'
import { dataSourceApi } from '../../api/platform'
import { developmentApi, metadataApi, releaseApi, type DataSourceView, type DevFile, type DevFolder, type DevProject, type DevelopmentBundle, type DevelopmentBundleRelease, type DevelopmentSchedule, type LineageView, type QueryResult } from '../../api/domain'

type DockPane='property'|'schedule'|'version'
type BottomPane='result'|'log'|'plan'|'lineage'|'scheduleDag'
type ResourceTarget={kind:'file'|'folder';id:number;name:string;folderId?:number;parentId?:number}
type TreeRow={kind:'file'|'folder';id:number;name:string;depth:number;file?:DevFile;folder?:DevFolder}

const projects=ref<DevProject[]>([]),folders=ref<DevFolder[]>([]),files=ref<DevFile[]>([]),sources=ref<DataSourceView[]>([]),databases=ref<string[]>([])
const projectId=ref<number>(),file=ref<DevFile>(),openFiles=ref<DevFile[]>([]),sourceId=ref<number>(),database=ref('')
const editorHost=ref<HTMLElement>(),editor=shallowRef<Monaco.editor.IStandaloneCodeEditor>(),editorLoading=ref(false),running=ref(false),saving=ref(false)
const codeDirty=ref(false),treeSearch=ref(''),groupMode=ref<'all'|'recent'|'mine'>('all'),activeBottom=ref<BottomPane>('result'),activeDock=ref<DockPane|null>('schedule')
const result=ref<QueryResult>(),logText=ref('暂无执行日志'),planText=ref('运行 SQL 后查看执行计划'),lineage=ref<LineageView[]>([])
const schedule=ref<DevelopmentSchedule>(),bundle=ref<DevelopmentBundle>(),releases=ref<DevelopmentBundleRelease[]>([])
const scheduleSaving=ref(false),publishOpen=ref(false),releaseDetailOpen=ref(false),selectedRelease=ref<DevelopmentBundleRelease>()
const expandedFolders=ref<Set<number>>(new Set())
const newFolderOpen=ref(false),newFolder=reactive({name:'',parentId:undefined as number|undefined})
const newTaskOpen=ref(false),newTask=reactive({name:'',type:'SQL',folderId:undefined as number|undefined,description:'',configureSchedule:false})
const moveOpen=ref(false),moveTarget=ref<ResourceTarget>(),moveFolderId=ref<number|undefined>()
const publishRemark=ref('统一发布代码与调度配置')
const propertyDescription=ref('')
const scheduleForm=reactive({enabled:false,cycleType:'DAILY',executionTime:'02:00',cronExpression:'0 0 2 * * ?',timezone:'Asia/Shanghai',dataSourceId:undefined as number|undefined,databaseName:'',bizDateParam:'${system.biz.date-1}',retryTimes:3,retryIntervalMinutes:5,timeoutMinutes:120,upstreamFileIds:[] as number[]})
let monacoApi:typeof import('monaco-editor/esm/vs/editor/editor.api')|null=null
let applyingContent=false

const currentName=computed(()=>stripExt(file.value?.name||'未打开任务'))
const currentType=computed(()=>file.value?.fileType?.toUpperCase()||'SQL')
const currentTypeLabel=computed(()=>({SQL:'SQL',SHELL:'Shell',PYTHON:'Python'} as Record<string,string>)[currentType.value]||currentType.value)
const isSql=computed(()=>currentType.value==='SQL')
const unsaved=computed(()=>Boolean(codeDirty.value||bundle.value?.sqlDirty||bundle.value?.scheduleDirty))
const currentSourceName=computed(()=>sources.value.find(x=>x.id===sourceId.value)?.name||'未选择 StarRocks')
const publishedCode=computed(()=>bundle.value?.publishedSqlVersion||0)
const publishedSchedule=computed(()=>bundle.value?.publishedScheduleVersion||0)
const scheduleDependencies=computed(()=>schedule.value?.dependencies||[])
const scheduleDownstream=computed(()=>schedule.value?.downstream||[])
const upstreamOptions=computed(()=>files.value.filter(x=>x.id!==file.value?.id&&x.fileType?.toUpperCase()==='SQL'))
const folderOptions=computed(()=>folders.value.map(f=>({id:f.id,label:folderPath(f)})).sort((a,b)=>a.label.localeCompare(b.label,'zh-CN')))
const moveFolderOptions=computed(()=>folderOptions.value.filter(x=>!(moveTarget.value?.kind==='folder'&&x.id===moveTarget.value.id)))

function stripExt(v:string){return v.replace(/\.(sql|sh|py)$/i,'')}
function fileTypeText(v?:string){return ({SQL:'SQL',SHELL:'SH',PYTHON:'PY'} as Record<string,string>)[(v||'SQL').toUpperCase()]||'TXT'}
function extensionOf(v:string){return v==='SHELL'?'.sh':v==='PYTHON'?'.py':'.sql'}
function languageOf(v?:string){return v?.toUpperCase()==='PYTHON'?'python':v?.toUpperCase()==='SHELL'?'shell':'sql'}
function defaultContent(type:string,name:string){if(type==='SHELL')return `#!/bin/bash\n# ${name}\n\necho "DataSphere task: ${name}"\n`;if(type==='PYTHON')return `# ${name}\n\ndef main():\n    print("DataSphere task: ${name}")\n\nif __name__ == "__main__":\n    main()\n`;return `-- ${name}\n\nSELECT\n    *\nFROM \nWHERE 1 = 1;`}
function msg(e:unknown){return e instanceof Error?e.message:'操作失败'}
function fmt(v?:string){return v?v.replace('T',' ').slice(0,19):'—'}
function cycleLabel(v:string){return ({DAILY:'每日',HOURLY:'每小时',WEEKLY:'每周',MONTHLY:'每月',CRON:'自定义 Cron'} as Record<string,string>)[v]||v}
function stateClass(f:DevFile){if(f.id===file.value?.id&&codeDirty.value)return'dirty';return f.status==='PUBLISHED'?'ok':'dirty'}
function folderPath(folder:DevFolder){const names=[folder.name];let p=folder.parentId;const seen=new Set<number>();while(p&& !seen.has(p)){seen.add(p);const parent=folders.value.find(x=>x.id===p);if(!parent)break;names.unshift(parent.name);p=parent.parentId}return names.join(' / ')}
function folderExpanded(id:number){return Boolean(treeSearch.value.trim())||expandedFolders.value.has(id)}
function toggleFolder(id:number){const next=new Set(expandedFolders.value);next.has(id)?next.delete(id):next.add(id);expandedFolders.value=next}
function fileVisible(f:DevFile){if(groupMode.value==='recent'&&!openFiles.value.some(x=>x.id===f.id))return false;const q=treeSearch.value.trim().toLowerCase();return !q||f.name.toLowerCase().includes(q)}
function folderMatches(folder:DevFolder):boolean{const q=treeSearch.value.trim().toLowerCase();if(!q)return true;if(folder.name.toLowerCase().includes(q))return true;if(files.value.some(f=>f.folderId===folder.id&&f.name.toLowerCase().includes(q)))return true;return folders.value.filter(x=>x.parentId===folder.id).some(folderMatches)}
const treeRows=computed<TreeRow[]>(()=>{const out:TreeRow[]=[];const walk=(parentId:number|undefined,depth:number)=>{const fs=folders.value.filter(x=>(x.parentId??undefined)===parentId).sort((a,b)=>a.name.localeCompare(b.name,'zh-CN'));for(const folder of fs){if(!folderMatches(folder))continue;out.push({kind:'folder',id:folder.id,name:folder.name,depth,folder});if(folderExpanded(folder.id))walk(folder.id,depth+1)}const direct=files.value.filter(x=>(x.folderId??undefined)===parentId&&fileVisible(x)).sort((a,b)=>a.name.localeCompare(b.name,'zh-CN'));for(const f of direct)out.push({kind:'file',id:f.id,name:f.name,depth,file:f})};walk(undefined,0);return out})

async function initEditor(){if(!editorHost.value||editor.value||editorLoading.value)return;editorLoading.value=true;try{monacoApi??=await import('monaco-editor/esm/vs/editor/editor.api');await Promise.all([import('monaco-editor/esm/vs/basic-languages/sql/sql.contribution'),import('monaco-editor/esm/vs/basic-languages/python/python.contribution'),import('monaco-editor/esm/vs/basic-languages/shell/shell.contribution')]);if(!editorHost.value)return;editor.value=monacoApi.editor.create(editorHost.value,{value:file.value?.content||'// 请选择开发任务',language:languageOf(file.value?.fileType),theme:'vs',automaticLayout:true,minimap:{enabled:false},fontSize:13,lineHeight:24,scrollBeyondLastLine:false,padding:{top:14},renderLineHighlight:'line'});editor.value.addCommand(monacoApi.KeyMod.CtrlCmd|monacoApi.KeyCode.Enter,()=>void runCode());editor.value.addCommand(monacoApi.KeyMod.CtrlCmd|monacoApi.KeyCode.KeyS,()=>void saveCode());editor.value.onDidChangeModelContent(()=>{if(!applyingContent)codeDirty.value=true})}catch(e){ElMessage.error('编辑器加载失败：'+msg(e))}finally{editorLoading.value=false}}
function setEditorContent(v:string,type?:string){if(!editor.value)return;applyingContent=true;editor.value.setValue(v||'');const model=editor.value.getModel();if(model&&monacoApi)monacoApi.editor.setModelLanguage(model,languageOf(type));codeDirty.value=false;queueMicrotask(()=>applyingContent=false)}

async function boot(){try{const [ps,ds]=await Promise.all([developmentApi.projects(),dataSourceApi.list()]);projects.value=ps;sources.value=ds.filter(x=>x.type==='STARROCKS');projectId.value=ps[0]?.id;sourceId.value=sources.value[0]?.id;if(sourceId.value)await loadDatabases();if(projectId.value)await loadResources();await nextTick();void initEditor()}catch(e){ElMessage.error(msg(e))}}
async function loadResources(preferred?:number){if(!projectId.value)return;const [fd,fl]=await Promise.all([developmentApi.folders(projectId.value),developmentApi.files(projectId.value)]);folders.value=fd;files.value=fl;if(!expandedFolders.value.size)expandedFolders.value=new Set(fd.filter(x=>!x.parentId).map(x=>x.id));if(file.value){const fresh=fl.find(x=>x.id===file.value?.id);if(fresh)file.value={...file.value,...fresh}}openFiles.value=openFiles.value.map(x=>fl.find(f=>f.id===x.id)||x);const target=fl.find(x=>x.id===preferred)||(!file.value?fl[0]:undefined);if(target)await openFile(target)}
async function loadDatabases(){if(!sourceId.value)return;const rows=await metadataApi.databases(sourceId.value,'STARROCKS');databases.value=rows.map(x=>x.name);if(!databases.value.includes(database.value))database.value=databases.value[0]||''}
async function openFile(row:DevFile){if(codeDirty.value&&file.value?.id!==row.id){try{await ElMessageBox.confirm('当前任务有未保存修改，仍然切换吗？','切换任务',{type:'warning'})}catch{return}}const detail=await developmentApi.getFile(row.id);file.value=detail;propertyDescription.value=detail.description||'';const idx=openFiles.value.findIndex(x=>x.id===detail.id);if(idx<0)openFiles.value.push(detail);else openFiles.value[idx]=detail;setEditorContent(detail.content,detail.fileType);await loadTaskMeta()}
async function loadTaskMeta(){if(!file.value)return;const [s,b,r]=await Promise.all([developmentApi.schedule(file.value.id),developmentApi.bundle(file.value.id),developmentApi.bundleReleases(file.value.id)]);schedule.value=s;bundle.value=b;releases.value=r;if(s.dataSourceId&&sources.value.some(x=>x.id===s.dataSourceId)){sourceId.value=s.dataSourceId;await loadDatabases();database.value=s.databaseName||database.value}fillSchedule(s);if(isSql.value)void loadLineage();else lineage.value=[]}
function fillSchedule(s:DevelopmentSchedule){Object.assign(scheduleForm,{enabled:s.enabled,cycleType:s.cycleType||'DAILY',executionTime:s.executionTime||'02:00',cronExpression:s.cronExpression||'0 0 2 * * ?',timezone:s.timezone||'Asia/Shanghai',dataSourceId:s.dataSourceId||sourceId.value,databaseName:s.databaseName||database.value,bizDateParam:s.bizDateParam||'${system.biz.date-1}',retryTimes:s.retryTimes??3,retryIntervalMinutes:s.retryIntervalMinutes??5,timeoutMinutes:s.timeoutMinutes??120,upstreamFileIds:s.dependencies.map(x=>x.fileId)})}

async function saveCode(){if(!file.value||!editor.value)return;saving.value=true;try{file.value=await developmentApi.saveFile(file.value.id,{content:editor.value.getValue(),name:file.value.name,description:file.value.description});codeDirty.value=false;ElMessage.success(`已保存为开发版本 V${file.value.currentVersion}，尚未发布`);await refreshBundle();await loadResources()}catch(e){ElMessage.error(msg(e))}finally{saving.value=false}}
async function saveProperty(){if(!file.value)return;try{file.value=await developmentApi.saveFile(file.value.id,{content:file.value.content,name:file.value.name,description:propertyDescription.value});await loadResources();ElMessage.success('任务属性已保存')}catch(e){ElMessage.error(msg(e))}}
async function runCode(){if(!file.value)return;if(!isSql.value)return ElMessage.warning(`${currentTypeLabel.value} 任务执行引擎尚未接入，当前仅支持 SQL 运行`);if(!sourceId.value||!editor.value)return ElMessage.warning('请选择 StarRocks 数据源');running.value=true;activeBottom.value='log';logText.value='正在提交 SQL 到 StarRocks...';try{const sql=editor.value.getModel()?.getValue()||'';result.value=await developmentApi.query(sql,sourceId.value,database.value||undefined);logText.value=`[${new Date().toLocaleTimeString()}] 提交 SQL 到 ${currentSourceName.value}\n数据库：${database.value||'—'}\n执行成功，返回 ${result.value.rowCount} 行\n总耗时 ${result.value.elapsedMs} ms`;activeBottom.value='result';ElMessage.success('SQL 执行成功')}catch(e){logText.value=msg(e);ElMessage.error(msg(e))}finally{running.value=false}}
async function loadPlan(){if(!isSql.value||!sourceId.value||!editor.value){planText.value='执行计划仅支持 SQL 任务';return}try{const r=await developmentApi.query('EXPLAIN '+editor.value.getValue(),sourceId.value,database.value||undefined);planText.value=r.rows.map(row=>Object.values(row).join('  ')).join('\n')||'暂无执行计划'}catch(e){planText.value=msg(e)}}
function formatCode(){editor.value?.getAction('editor.action.formatDocument')?.run()}
async function refreshBundle(){if(!file.value)return;bundle.value=await developmentApi.bundle(file.value.id);releases.value=await developmentApi.bundleReleases(file.value.id)}
function toggleDock(type:DockPane){activeDock.value=activeDock.value===type?null:type;if(type==='schedule'&&activeDock.value&&schedule.value)fillSchedule(schedule.value)}
function closeDock(){activeDock.value=null}
async function onScheduleSourceChange(){sourceId.value=scheduleForm.dataSourceId;await loadDatabases();scheduleForm.databaseName=databases.value[0]||''}
function syncCron(){const t=scheduleForm.executionTime||'02:00',[h,m]=t.split(':').map(Number);if(scheduleForm.cycleType==='DAILY')scheduleForm.cronExpression=`0 ${m||0} ${h||0} * * ?`;else if(scheduleForm.cycleType==='HOURLY')scheduleForm.cronExpression=`0 ${m||0} * * * ?`;else if(scheduleForm.cycleType==='WEEKLY')scheduleForm.cronExpression=`0 ${m||0} ${h||0} ? * MON`;else if(scheduleForm.cycleType==='MONTHLY')scheduleForm.cronExpression=`0 ${m||0} ${h||0} 1 * ?`}
async function saveSchedule(){if(!file.value)return;if(!isSql.value)return ElMessage.warning('当前仅 SQL 开发任务支持生产调度');if(!scheduleForm.dataSourceId)return ElMessage.warning('请选择 StarRocks 数据源');scheduleSaving.value=true;try{schedule.value=await developmentApi.saveSchedule(file.value.id,{...scheduleForm,dataSourceId:scheduleForm.dataSourceId,upstreamFileIds:[...scheduleForm.upstreamFileIds]});fillSchedule(schedule.value);await refreshBundle();ElMessage.success(`调度已保存为 S${schedule.value.currentVersion}，尚未发布`)}catch(e){ElMessage.error(msg(e))}finally{scheduleSaving.value=false}}
async function loadLineage(){if(!file.value||!isSql.value)return;try{lineage.value=await metadataApi.lineage(currentName.value)}catch{lineage.value=[]}}
async function switchBottom(v:BottomPane){activeBottom.value=v;if(v==='lineage')await loadLineage();if(v==='plan')await loadPlan()}

function handleNew(command:string){if(command==='folder'){newFolder.name='';newFolder.parentId=undefined;newFolderOpen.value=true}else{newTask.name='';newTask.type='SQL';newTask.folderId=undefined;newTask.description='';newTask.configureSchedule=false;newTaskOpen.value=true}}
async function createFolder(){if(!projectId.value||!newFolder.name.trim())return;try{const created=await developmentApi.createFolder({projectId:projectId.value,parentId:newFolder.parentId,name:newFolder.name.trim()});newFolderOpen.value=false;expandedFolders.value=new Set([...expandedFolders.value,created.id]);await loadResources();ElMessage.success('文件夹已创建')}catch(e){ElMessage.error(msg(e))}}
async function createTask(){if(!projectId.value||!newTask.name.trim())return;try{const base=newTask.name.trim().replace(/\s+/g,'_').replace(/\.(sql|sh|py)$/i,'');const ext=extensionOf(newTask.type);const name=base+ext;const created=await developmentApi.createFile({projectId:projectId.value,folderId:newTask.folderId,name,fileType:newTask.type,content:defaultContent(newTask.type,base),description:newTask.description});if(newTask.folderId)expandedFolders.value=new Set([...expandedFolders.value,newTask.folderId]);newTaskOpen.value=false;await loadResources(created.id);if(newTask.configureSchedule&&newTask.type==='SQL')activeDock.value='schedule';ElMessage.success('开发任务已创建并打开')}catch(e){ElMessage.error(msg(e))}}
function resourceTarget(row:TreeRow):ResourceTarget{return row.kind==='file'?{kind:'file',id:row.id,name:row.name,folderId:row.file?.folderId}:{kind:'folder',id:row.id,name:row.name,parentId:row.folder?.parentId}}
async function resourceCommand(command:string,row:TreeRow){const target=resourceTarget(row);if(command==='rename')return renameResource(target);if(command==='move'){moveTarget.value=target;moveFolderId.value=target.kind==='file'?target.folderId:target.parentId;moveOpen.value=true;return}if(command==='delete')return deleteResource(target)}
async function renameResource(target:ResourceTarget){try{const r=await ElMessageBox.prompt(`请输入新的${target.kind==='folder'?'文件夹':'任务'}名称`,'重命名',{inputValue:target.kind==='file'?stripExt(target.name):target.name,confirmButtonText:'保存',cancelButtonText:'取消',inputPattern:/^[^\\/:*?"<>|]+$/,inputErrorMessage:'名称不合法'});if(target.kind==='folder'){const folder=folders.value.find(x=>x.id===target.id)!;await developmentApi.updateFolder(target.id,{name:r.value.trim(),parentId:folder.parentId,moveToRoot:!folder.parentId})}else{const detail=await developmentApi.getFile(target.id);const ext=detail.name.match(/\.(sql|sh|py)$/i)?.[0]||extensionOf(detail.fileType.toUpperCase());await developmentApi.saveFile(target.id,{content:detail.content,name:r.value.trim().replace(/\.(sql|sh|py)$/i,'')+ext,description:detail.description,folderId:detail.folderId,moveToRoot:!detail.folderId})}await loadResources();ElMessage.success('重命名成功')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(msg(e))}}
async function confirmMove(){const target=moveTarget.value;if(!target)return;try{if(target.kind==='folder'){await developmentApi.updateFolder(target.id,{name:target.name,parentId:moveFolderId.value,moveToRoot:!moveFolderId.value})}else{const detail=await developmentApi.getFile(target.id);await developmentApi.saveFile(target.id,{content:detail.content,name:detail.name,description:detail.description,folderId:moveFolderId.value,moveToRoot:!moveFolderId.value})}moveOpen.value=false;await loadResources();ElMessage.success('移动成功')}catch(e){ElMessage.error(msg(e))}}
async function deleteResource(target:ResourceTarget){try{await ElMessageBox.confirm(`确认删除${target.kind==='folder'?'文件夹':'开发任务'}“${target.name}”？`,'删除确认',{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'});if(target.kind==='folder')await developmentApi.deleteFolder(target.id);else await developmentApi.deleteFile(target.id);if(target.kind==='file'){openFiles.value=openFiles.value.filter(x=>x.id!==target.id);if(file.value?.id===target.id){file.value=undefined;setEditorContent('// 请选择开发任务','SQL')}}await loadResources();ElMessage.success('删除成功')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(msg(e))}}

function openPublish(){if(!file.value)return;publishRemark.value='统一发布代码与调度配置';publishOpen.value=true}
async function publishBundle(){if(!file.value)return;try{const req=await releaseApi.request({resourceType:'DEVELOPMENT',resourceId:file.value.id,resourceName:file.value.name,requestedVersion:file.value.currentVersion,payload:{remark:publishRemark.value,scheduleVersion:bundle.value?.scheduleVersion||0}});publishOpen.value=false;if(req.status==='PENDING_APPROVAL')ElMessage.success('发布申请已提交，等待审批');else ElMessage.success('代码与调度已统一发布');await loadTaskMeta()}catch(e){ElMessage.error(msg(e))}}
function showRelease(r:DevelopmentBundleRelease){selectedRelease.value=r;releaseDetailOpen.value=true}
async function rollbackRelease(){if(!file.value||!selectedRelease.value)return;try{await ElMessageBox.confirm(`确认将生产整体回滚到 P${selectedRelease.value.releaseNo}？代码与调度会一起回滚。`,'整体回滚',{type:'warning'});await developmentApi.rollbackBundle(file.value.id,selectedRelease.value.releaseNo);releaseDetailOpen.value=false;await loadTaskMeta();ElMessage.success(`已回滚到 P${selectedRelease.value.releaseNo}`)}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(msg(e))}}
async function closeTab(tab:DevFile,e:Event){e.stopPropagation();if(tab.id===file.value?.id&&codeDirty.value){try{await ElMessageBox.confirm('当前任务有未保存修改，确认关闭？','关闭任务',{type:'warning'})}catch{return}}const idx=openFiles.value.findIndex(x=>x.id===tab.id);openFiles.value.splice(idx,1);if(tab.id===file.value?.id){const next=openFiles.value[Math.max(0,idx-1)];if(next)await openFile(next);else{file.value=undefined;setEditorContent('// 请选择开发任务','SQL')}}}

onMounted(boot);onBeforeUnmount(()=>editor.value?.dispose())
</script>

<template>
<div class="dev-ide"><div class="workbench">
  <aside class="sidebar">
    <div class="side-head"><strong>开发目录</strong><el-dropdown trigger="click" @command="handleNew"><el-button type="primary" size="small" :icon="Plus">新建</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="folder"><span class="new-menu-icon">📁</span>文件夹</el-dropdown-item><el-dropdown-item command="task"><span class="new-menu-icon">▣</span>开发任务</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div>
    <div class="side-search"><el-input v-model="treeSearch" size="small" placeholder="搜索开发任务..." :prefix-icon="Search" clearable/></div>
    <div class="group-switch"><button v-for="x in [{k:'all',n:'全部'},{k:'recent',n:'最近打开'},{k:'mine',n:'我的任务'}]" :key="x.k" :class="['pill',{active:groupMode===x.k}]" @click="groupMode=x.k as any">{{x.n}}</button></div>
    <div class="tree">
      <div v-for="row in treeRows" :key="row.kind+'-'+row.id" class="tree-row" :class="[{selected:row.kind==='file'&&file?.id===row.id},row.kind]" :style="{paddingLeft:(8+row.depth*18)+'px'}" @click="row.kind==='folder'?toggleFolder(row.id):openFile(row.file!)">
        <span v-if="row.kind==='folder'" class="chev">{{folderExpanded(row.id)?'⌄':'›'}}</span><el-icon v-if="row.kind==='folder'" class="folder-icon"><Folder/></el-icon><span v-else class="file-ico" :class="(row.file?.fileType||'SQL').toLowerCase()">{{fileTypeText(row.file?.fileType)}}</span><span class="resource-name">{{row.kind==='file'?stripExt(row.name):row.name}}</span><span v-if="row.kind==='file'" :class="['task-state',stateClass(row.file!)]"></span>
        <el-dropdown trigger="click" @command="(c:string)=>resourceCommand(c,row)" @click.stop><button class="resource-more" @click.stop><el-icon><MoreFilled/></el-icon></button><template #dropdown><el-dropdown-menu><el-dropdown-item command="rename">重命名</el-dropdown-item><el-dropdown-item command="move">移动</el-dropdown-item><el-dropdown-item divided command="delete"><span class="danger-text">删除</span></el-dropdown-item></el-dropdown-menu></template></el-dropdown>
      </div>
      <div v-if="!treeRows.length" class="tree-empty">暂无开发任务</div>
    </div><div class="side-foot">生产空间 · 默认工作目录</div>
  </aside>

  <main class="center">
    <div class="tabs"><button v-for="tab in openFiles" :key="tab.id" :class="['tab',{active:file?.id===tab.id,dirty:file?.id===tab.id&&codeDirty}]" @click="openFile(tab)"><span class="dot"></span><span>{{tab.name}}</span><el-icon class="close" @click="closeTab(tab,$event)"><Close/></el-icon></button><el-dropdown trigger="click" @command="handleNew"><button class="plus">＋</button><template #dropdown><el-dropdown-menu><el-dropdown-item command="folder">文件夹</el-dropdown-item><el-dropdown-item command="task">开发任务</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div>
    <div class="toolbar"><div class="meta"><span class="title">{{currentName}}</span><span class="badge dev">开发 V{{file?.currentVersion||0}}</span><span class="badge prod">生产 P{{bundle?.releaseNo||0}}</span><span :class="['badge',unsaved?'dirty':'prod']">{{unsaved?'● 有未发布变更':'✓ 已发布'}}</span></div><div class="actions"><el-button size="small" :loading="saving" @click="saveCode">保存 <span class="shortcut">Ctrl+S</span></el-button><el-button size="small" class="run" :loading="running" @click="runCode">▶ 运行 <span class="shortcut">Ctrl+Enter</span></el-button><el-button size="small" @click="formatCode">格式化</el-button><el-button size="small" type="primary" @click="openPublish">提交发布</el-button><el-dropdown trigger="click"><el-button size="small">···</el-button><template #dropdown><el-dropdown-menu v-if="file"><el-dropdown-item @click="renameResource({kind:'file',id:file.id,name:file.name,folderId:file.folderId})">重命名任务</el-dropdown-item><el-dropdown-item @click="moveTarget={kind:'file',id:file.id,name:file.name,folderId:file.folderId};moveFolderId=file.folderId;moveOpen=true">移动任务</el-dropdown-item><el-dropdown-item divided @click="deleteResource({kind:'file',id:file.id,name:file.name,folderId:file.folderId})"><span class="danger-text">删除任务</span></el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></div>

    <div class="middle"><div class="editor"><div ref="editorHost" class="editor-host"></div><div v-if="editorLoading&&!editor" class="editor-loading">正在加载编辑器…</div></div><div class="inspector-wrap">
      <section class="drawer" :class="{open:activeDock}"><div class="drawer-head"><strong>{{activeDock==='property'?'任务属性':activeDock==='schedule'?'调度配置':'版本管理'}}</strong><button class="x" @click="closeDock">×</button></div><div class="drawer-body">
        <div v-if="activeDock==='property'"><div class="section"><div class="section-title">基本属性</div><dl class="kv"><dt>任务名称</dt><dd>{{currentName}}</dd><dt>任务类型</dt><dd>{{currentTypeLabel}}</dd><dt>负责人</dt><dd>{{projects.find(x=>x.id===projectId)?.ownerName||'admin'}}</dd><dt>开发版本</dt><dd>V{{file?.currentVersion||0}}</dd><dt>生产版本</dt><dd>P{{bundle?.releaseNo||0}}</dd><dt>更新时间</dt><dd>{{fmt(file?.updatedAt)}}</dd></dl></div><div class="divider"></div><div class="form"><label>任务描述</label><textarea v-model="propertyDescription" @change="saveProperty"></textarea></div><div class="section"><div class="section-title">运行参数</div><div class="dep-item"><span>biz_date</span><span>{{isSql?scheduleForm.bizDateParam:'—'}}</span></div></div></div>
        <div v-else-if="activeDock==='schedule'"><template v-if="isSql"><div class="section"><div class="section-title">运行环境 <span class="help">真实 StarRocks 配置</span></div><div class="form"><label>StarRocks 数据源</label><el-select v-model="scheduleForm.dataSourceId" filterable @change="onScheduleSourceChange"><el-option v-for="s in sources" :key="s.id" :label="s.name" :value="s.id"/></el-select></div><div class="form"><label>Database</label><el-select v-model="scheduleForm.databaseName" filterable><el-option v-for="d in databases" :key="d" :label="d" :value="d"/></el-select></div></div><div class="divider"></div><div class="section"><div class="section-title">基本调度 <span class="help">修改后需重新发布</span></div><div class="form"><label>调度状态</label><el-select v-model="scheduleForm.enabled"><el-option label="已启用" :value="true"/><el-option label="已停用" :value="false"/></el-select></div><div class="two"><div class="form"><label>调度周期</label><el-select v-model="scheduleForm.cycleType" @change="syncCron"><el-option label="每日" value="DAILY"/><el-option label="每小时" value="HOURLY"/><el-option label="每周" value="WEEKLY"/><el-option label="每月" value="MONTHLY"/><el-option label="自定义 Cron" value="CRON"/></el-select></div><div class="form"><label>执行时间</label><el-time-picker v-model="scheduleForm.executionTime" value-format="HH:mm" format="HH:mm" style="width:100%" @change="syncCron"/></div></div><div class="form"><label>Cron 表达式</label><el-input v-model="scheduleForm.cronExpression"/></div><div class="form"><label>时区</label><el-select v-model="scheduleForm.timezone"><el-option label="Asia/Shanghai" value="Asia/Shanghai"/><el-option label="UTC" value="UTC"/></el-select></div></div><div class="divider"></div><div class="section"><div class="section-title">上游依赖 <span class="help">成功后执行</span></div><el-select v-model="scheduleForm.upstreamFileIds" multiple filterable collapse-tags style="width:100%" placeholder="选择上游任务"><el-option v-for="f in upstreamOptions" :key="f.id" :label="stripExt(f.name)" :value="f.id"/></el-select><div class="dep-list"><div v-for="d in scheduleDependencies" :key="d.fileId" class="dep-item"><span>{{stripExt(d.name)}}</span><span>成功后执行</span></div><div v-if="!scheduleDependencies.length" class="dep-empty">暂无已保存上游依赖</div></div></div><div class="divider"></div><div class="section"><div class="section-title">运行参数</div><div class="form"><label>biz_date</label><el-select v-model="scheduleForm.bizDateParam"><el-option label="${system.biz.date-1}" value="${system.biz.date-1}"/><el-option label="${system.biz.date}" value="${system.biz.date}"/><el-option label="${system.date}" value="${system.date}"/></el-select></div></div><div class="divider"></div><div class="section"><div class="section-title">失败策略</div><div class="two"><div class="form"><label>失败重试次数</label><el-input-number v-model="scheduleForm.retryTimes" :min="0" :max="20"/></div><div class="form"><label>重试间隔（分钟）</label><el-input-number v-model="scheduleForm.retryIntervalMinutes" :min="1" :max="1440"/></div></div><div class="form"><label>任务超时（分钟）</label><el-input-number v-model="scheduleForm.timeoutMinutes" :min="1" :max="10080"/></div></div></template><el-empty v-else :description="`${currentTypeLabel} 任务执行引擎尚未接入，暂不支持生产调度`"/></div>
        <div v-else-if="activeDock==='version'"><div class="section-title">发布版本 <span class="help">代码 + 调度统一发布</span></div><div v-if="unsaved" class="version-card current"><div class="vh"><b>待发布 · 开发中</b><small>当前</small></div><div class="vmeta"><span>代码</span><span>V{{file?.currentVersion||0}}</span><span>调度</span><span>S{{bundle?.scheduleVersion||0}}</span><span>状态</span><span>有未发布变更</span></div><div class="version-actions"><span class="link" @click="openPublish">提交发布</span></div></div><div v-for="r in releases" :key="r.releaseNo" class="version-card" :class="{current:r.current}"><div class="vh"><b>P{{r.releaseNo}} {{r.current?'· 当前生产':''}}</b><small>{{fmt(r.releasedAt)}}</small></div><div class="vmeta"><span>代码</span><span>V{{r.sqlVersion}}</span><span>调度</span><span>S{{r.scheduleVersion}}</span><span>发布人</span><span>{{r.operatorName}}</span></div><div class="version-actions"><span class="link" @click="showRelease(r)">查看详情</span><span v-if="!r.current" class="link" @click="selectedRelease=r;rollbackRelease()">回滚</span></div></div><el-empty v-if="!releases.length&&!unsaved" description="暂无发布版本"/></div>
      </div><div v-if="activeDock==='schedule'&&isSql" class="drawer-foot"><el-button size="small" @click="closeDock">取消</el-button><el-button size="small" type="primary" :loading="scheduleSaving" @click="saveSchedule">保存调度配置</el-button></div></section>
      <nav class="dock"><button :class="['dock-btn',{active:activeDock==='property'}]" @click="toggleDock('property')"><span class="i">⚙</span><span>属性</span></button><button :class="['dock-btn',{active:activeDock==='schedule'}]" @click="toggleDock('schedule')"><span class="i">◷</span><span>调度</span></button><button :class="['dock-btn',{active:activeDock==='version'}]" @click="toggleDock('version')"><span class="i">⑂</span><span>版本</span></button><div class="dock-spacer"></div></nav>
    </div></div>

    <section class="bottom"><div class="bottom-tabs"><div class="btabs"><button v-for="x in [{k:'result',n:'运行结果'},{k:'log',n:'执行日志'},{k:'plan',n:'执行计划'},{k:'lineage',n:'数据血缘'},{k:'scheduleDag',n:'调度依赖'}]" :key="x.k" :class="['btab',{active:activeBottom===x.k}]" @click="switchBottom(x.k as BottomPane)">{{x.n}}</button></div><div class="runstatus">{{result?.status==='SUCCESS'?`✓ 最近执行成功 · ${result.elapsedMs} ms · ${result.rowCount} 行`:'运行任务后查看结果'}}</div></div><div class="panel"><div v-if="activeBottom==='result'"><el-table v-if="result?.rows?.length" :data="result.rows" height="180" size="small"><el-table-column v-for="c in result.columns" :key="c" :prop="c" :label="c" min-width="130"/></el-table><div v-else class="empty">暂无运行结果</div></div><pre v-else-if="activeBottom==='log'" class="log">{{logText}}</pre><pre v-else-if="activeBottom==='plan'" class="plan">{{planText}}</pre><div v-else-if="activeBottom==='lineage'" class="dag"><template v-if="lineage.length"><div v-for="x in lineage" :key="x.id" class="lineage-item"><div class="node"><b>{{x.sourceTable}}</b><span>数据表</span></div><div class="arrow">→</div><div class="node focus"><b>{{x.targetTable}}</b><span>当前产出表</span></div></div></template><div v-else class="empty">暂无数据血缘</div></div><div v-else class="dag"><div class="dag-col"><div v-for="d in scheduleDependencies" :key="d.fileId" class="node"><b>{{stripExt(d.name)}}</b><span>上游任务 · 成功后执行</span></div></div><div class="arrow">→</div><div class="node focus"><b>{{currentName}}</b><span>当前任务 · {{cycleLabel(schedule?.cycleType||'DAILY')}} {{schedule?.executionTime||'—'}}</span></div><div class="arrow">→</div><div class="dag-col"><div v-for="d in scheduleDownstream" :key="d.fileId" class="node"><b>{{stripExt(d.name)}}</b><span>下游任务</span></div></div></div></div></section>
    <div class="statusbar"><div><span><span class="gdot" :class="{muted:!isSql}"></span>{{isSql?'StarRocks 已连接':'本地开发任务'}}</span><span>{{isSql?currentSourceName:'生产空间'}}</span><span>{{isSql?(database||'—'):currentTypeLabel}}</span></div><div><span>UTF-8</span><span>{{currentTypeLabel}}</span><span>自动保存：关闭</span></div></div>
  </main>
</div>

<el-dialog v-model="newFolderOpen" title="新建文件夹" width="460px"><el-form label-position="top"><el-form-item label="文件夹名称 *"><el-input v-model="newFolder.name" placeholder="请输入文件夹名称"/></el-form-item><el-form-item label="上级文件夹"><el-select v-model="newFolder.parentId" clearable filterable placeholder="根目录"><el-option v-for="x in folderOptions" :key="x.id" :label="x.label" :value="x.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="newFolderOpen=false">取消</el-button><el-button type="primary" @click="createFolder">创建</el-button></template></el-dialog>
<el-dialog v-model="newTaskOpen" title="新建开发任务" width="560px"><el-form label-position="top"><div class="dialog-grid"><el-form-item label="任务名称 *"><el-input v-model="newTask.name" placeholder="例如：dwd_order_detail"/></el-form-item><el-form-item label="任务类型 *"><el-select v-model="newTask.type"><el-option label="SQL" value="SQL"/><el-option label="Shell" value="SHELL"/><el-option label="Python" value="PYTHON"/></el-select></el-form-item><el-form-item label="所属文件夹"><el-select v-model="newTask.folderId" clearable filterable placeholder="根目录"><el-option v-for="x in folderOptions" :key="x.id" :label="x.label" :value="x.id"/></el-select></el-form-item><el-form-item label="负责人"><el-input :model-value="projects.find(x=>x.id===projectId)?.ownerName||'admin'" disabled/></el-form-item></div><el-form-item label="任务描述"><el-input v-model="newTask.description" type="textarea"/></el-form-item><el-checkbox v-model="newTask.configureSchedule" :disabled="newTask.type!=='SQL'">创建后打开调度配置</el-checkbox></el-form><template #footer><el-button @click="newTaskOpen=false">取消</el-button><el-button type="primary" @click="createTask">创建并打开</el-button></template></el-dialog>
<el-dialog v-model="moveOpen" :title="`移动${moveTarget?.kind==='folder'?'文件夹':'开发任务'}`" width="480px"><el-form label-position="top"><el-form-item label="目标文件夹"><el-select v-model="moveFolderId" clearable filterable placeholder="根目录"><el-option v-for="x in moveFolderOptions" :key="x.id" :label="x.label" :value="x.id"/></el-select></el-form-item></el-form><template #footer><el-button @click="moveOpen=false">取消</el-button><el-button type="primary" @click="confirmMove">移动</el-button></template></el-dialog>

<el-dialog v-model="publishOpen" title="提交发布" width="820px"><div class="release-strip"><strong>P{{(bundle?.releaseNo||0)+1}}</strong><span>=</span><span>开发 V{{file?.currentVersion||0}}</span><span>+</span><span>调度 S{{bundle?.scheduleVersion||0}}</span><span class="push-right">当前生产 P{{bundle?.releaseNo||0}}</span></div><el-form label-position="top"><div class="dialog-grid"><el-form-item label="任务名称"><el-input :model-value="currentName" disabled/></el-form-item><el-form-item label="变更说明 *"><el-input v-model="publishRemark"/></el-form-item></div></el-form><div class="check-title">发布前检查</div><div class="checks"><div><span>代码已保存</span><b class="ok">{{codeDirty?'需先保存':'✓ 通过'}}</b></div><div v-if="isSql"><span>StarRocks 数据源</span><b class="ok">{{scheduleForm.dataSourceId?'✓ 已配置':'未配置'}}</b></div><div><span>任务权限</span><b class="ok">✓ 通过</b></div></div><template #footer><el-button @click="publishOpen=false">取消</el-button><el-button type="primary" :disabled="codeDirty" @click="publishBundle">确认发布</el-button></template></el-dialog>
<el-dialog v-model="releaseDetailOpen" :title="`发布版本 P${selectedRelease?.releaseNo||''}`" width="680px"><div v-if="selectedRelease" class="release-strip"><strong>P{{selectedRelease.releaseNo}}</strong><span>开发 V{{selectedRelease.sqlVersion}} + 调度 S{{selectedRelease.scheduleVersion}}</span><span class="push-right">{{selectedRelease.current?'当前生产':'历史'}}</span></div><div v-if="selectedRelease" class="change-grid release-detail"><div><b>代码版本</b><p>V{{selectedRelease.sqlVersion}}</p></div><div><b>调度配置</b><p>S{{selectedRelease.scheduleVersion}}</p><p>{{selectedRelease.remark||'统一发布'}}</p></div></div><template #footer><el-button @click="releaseDetailOpen=false">关闭</el-button><el-button v-if="selectedRelease&&!selectedRelease.current" type="primary" @click="rollbackRelease">回滚到此发布版本</el-button></template></el-dialog>
</div>
</template>

